// Keys whose live text is rendered at the call site (digit-formatted numbers,
// two different short units) while the dictionary entry is the canonical
// translation. For these, a caller-supplied fallback wins over the dictionary
// value, so the dynamic digits/unit never get replaced by a static label or a
// literal {placeholder}. Without a fallback the resolver still returns the
// dictionary value normally (no raw key is ever shown).
const LIVE_FALLBACK_KEYS = new Set<string>([
  'mv.compaction',
  'mv.findings.count',
  'mv.unit.lines',
  'sb.led.state',
  'set.updates.feed.hint.v1131',
]);

export function makeT(lang: Lang) {
  const idx = lang === 'ar' ? 1 : 0;
  return (key: string, fallback?: string, params?: Record<string, string | number>): string => {
    const e = D[key];
    let out = LIVE_FALLBACK_KEYS.has(key) && fallback !== undefined
      ? fallback
      : e ? e[idx] || e[0] : fallback ?? key;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        out = out.split(`{${k}}`).join(String(v));
      }
    }
    return out;
  };
}

export function useT() {
  const lang = useStore((s) => s.settings?.language ?? 'en');
  return makeT(lang);
}

// ── v7.2 numerals — Arabic-Indic digit rendering for badges/dates ──
/** '0'-'9' → '٠'-'٩' (Arabic-Indic). Pass-through for everything else. */
export function toArabicDigits(v: string | number): string {
  return String(v).replace(/[0-9]/g, (d) => '٠١٢٣٤٥٦٧٨٩'[Number(d)]);
}

/**
 * Selector hook — returns a digit formatter honoring settings.numerals.
 * `n(123)` → "123" (western, default) or "١٢٣" (arabic). Used by status-bar
 * badges, cost/token readouts and transcript time gutters so the Arabic UI
 * can render numbers natively instead of forcing Latin digits everywhere.
 */
export function useDigits(): (v: string | number) => string {
  const numerals = useStore((s) => s.settings?.numerals ?? 'western');
  if (numerals === 'arabic') return toArabicDigits;
  return (v) => String(v);
}

