// ═══════════════════════════════════════════════════════════════
// v11.22 — HONEST FAILURE MESSAGES (founder: no raw EN, no mixed
// EN+AR when one language is selected). Every value below is a
// strictly monolingual [en, ar] pair, says exactly WHAT was missing
// and the EXACT next step. These are the canonical keys that the
// store.ts / register.ts fix agents (A6/A7) must call via t(key):
//
//   err.run.badParams          — run request had no messages / no model
//   err.run.noUserMessage      — composer had no user message to send
//   err.run.rateLimited        — provider returned 429 / rate limit
//   err.run.providerUnavailable— provider unreachable / 5xx / offline
//   err.setup.noModel          — no model configured or selected
//   err.setup.noWorkspace      — no workspace folder open
//   err.setup.noApiKey         — provider has no API key configured
//   err.setup.noCredits        — provider credits exhausted (402; reuses
//                                the existing v11.19 noCreditsToast wording)
//
// Owned by the i18n agent only — do not inline translations elsewhere.
// ═══════════════════════════════════════════════════════════════
